    bronze_grainmoisturemeter = { name = "Bronast merilec vlage žita", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast merilec vlage žita za mlinarje." },
    silver_grainmoisturemeter = { name = "Srebrn merilec vlage žita", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn merilec vlage žita za mlinarje." },
