    sovereign_grainmoisturemeter_palace = { name = "Suverena grainmoisturemeter palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainMoistureMeterMaker.ironStock=14; GrainMoistureMeterMaker.bronzeStock=12; GrainMoistureMeterMaker.woodStock=12; GrainMoistureMeterMaker.leatherStock=8; GrainMoistureMeterMaker.silverStock=8; GrainMoistureMeterMaker.goldStock=6; GrainMoistureMeterMaker.jewelStock=4; GrainMoistureMeterMaker.pearlStock=4
GrainMoistureMeterMaker.productStock = {}; GrainMoistureMeterMaker.buildings = {}; GrainMoistureMeterMaker.maker = nil; GrainMoistureMeterMaker.activeMaking = {}; GrainMoistureMeterMaker.totalProducts = 0; GrainMoistureMeterMaker.dayTimer = 0
function GrainMoistureMeterMaker.init() GrainMoistureMeterMaker.ironStock=14; GrainMoistureMeterMaker.bronzeStock=12; GrainMoistureMeterMaker.woodStock=12; GrainMoistureMeterMaker.leatherStock=8; GrainMoistureMeterMaker.silverStock=8; GrainMoistureMeterMaker.goldStock=6; GrainMoistureMeterMaker.jewelStock=4; GrainMoistureMeterMaker.pearlStock=4; GrainMoistureMeterMaker.productStock={}; GrainMoistureMeterMaker.buildings={}; GrainMoistureMeterMaker.maker=nil; GrainMoistureMeterMaker.activeMaking={}; GrainMoistureMeterMaker.totalProducts=0; GrainMoistureMeterMaker.dayTimer=0; print("[GrainMoistureMeterMaker] Royal Grain Moisture Meter Maker System initialized (6 products, 4 buildings)") end
function GrainMoistureMeterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainMoistureMeterMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",GrainMoistureMeterMaker.maker.name,s),"success") end; return true end
function GrainMoistureMeterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainMoistureMeterMaker.build(id) local ok,e=GrainMoistureMeterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainMoistureMeterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainMoistureMeterMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainMoistureMeterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainMoistureMeterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainMoistureMeterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainMoistureMeterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainMoistureMeterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainMoistureMeterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainMoistureMeterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainMoistureMeterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainMoistureMeterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainMoistureMeterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainMoistureMeterMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not GrainMoistureMeterMaker.maker then return false,"Potreben merilnik" end; return true end
function GrainMoistureMeterMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainMoistureMeterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainMoistureMeterMaker.ironStock=GrainMoistureMeterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainMoistureMeterMaker.bronzeStock=GrainMoistureMeterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainMoistureMeterMaker.woodStock=GrainMoistureMeterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainMoistureMeterMaker.leatherStock=GrainMoistureMeterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainMoistureMeterMaker.silverStock=GrainMoistureMeterMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainMoistureMeterMaker.goldStock=GrainMoistureMeterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainMoistureMeterMaker.jewelStock=GrainMoistureMeterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainMoistureMeterMaker.pearlStock=GrainMoistureMeterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainMoistureMeterMaker.maker then t=math.max(1,t-math.floor(GrainMoistureMeterMaker.maker.skill/13)) end; table.insert(GrainMoistureMeterMaker.activeMaking,{id="grainmoisturemeter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainMoistureMeterMaker.completeMaking(m) local q=1.0+(GrainMoistureMeterMaker.getQualityBonus()/100); if GrainMoistureMeterMaker.maker then q=q+(GrainMoistureMeterMaker.maker.skill/140) end; q=math.min(2.5,q); GrainMoistureMeterMaker.productStock[m.productType]=(GrainMoistureMeterMaker.productStock[m.productType] or 0)+m.quantity; GrainMoistureMeterMaker.totalProducts=GrainMoistureMeterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainMoistureMeterMaker.maker then GrainMoistureMeterMaker.maker.itemsMade=GrainMoistureMeterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainMoistureMeterMaker.maker.skill=math.min(100,GrainMoistureMeterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainmoisturemeter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainMoistureMeterMaker.update(dt) if not _G.state then return end; GrainMoistureMeterMaker.dayTimer=GrainMoistureMeterMaker.dayTimer+dt; if GrainMoistureMeterMaker.dayTimer>=30 then GrainMoistureMeterMaker.dayTimer=0; for i=#GrainMoistureMeterMaker.activeMaking,1,-1 do local m=GrainMoistureMeterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainMoistureMeterMaker.completeMaking(m); table.remove(GrainMoistureMeterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainMoistureMeterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainMoistureMeterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainMoistureMeterMaker.getStats() return {ironStock=GrainMoistureMeterMaker.ironStock,bronzeStock=GrainMoistureMeterMaker.bronzeStock,woodStock=GrainMoistureMeterMaker.woodStock,leatherStock=GrainMoistureMeterMaker.leatherStock,silverStock=GrainMoistureMeterMaker.silverStock,goldStock=GrainMoistureMeterMaker.goldStock,jewelStock=GrainMoistureMeterMaker.jewelStock,pearlStock=GrainMoistureMeterMaker.pearlStock,productStock=GrainMoistureMeterMaker.productStock,numBuildings=#GrainMoistureMeterMaker.buildings,hasMaker=GrainMoistureMeterMaker.maker~=nil,makerName=GrainMoistureMeterMaker.maker and GrainMoistureMeterMaker.maker.name or "—",makerSkill=GrainMoistureMeterMaker.maker and GrainMoistureMeterMaker.maker.skill or 0,activeMaking=#GrainMoistureMeterMaker.activeMaking,totalProducts=GrainMoistureMeterMaker.totalProducts} end
